    internal static string NormalizeDefinition(string sql)
        => string.Join(' ', sql.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries));

    internal static bool IsSourceShiftValidation(string migrationId, SqlOperation operation)
    {
        if (migrationId != "20261006170000_PreserveHeldOrderShiftChanges"
            || NormalizeDefinition(operation.Sql) != SourceShiftValidationSql) return false;
        if (operation.SuppressTransaction)
            throw new InvalidOperationException("Delivery source validation must run inside the migration transaction.");
        return true;
    }

    internal static bool IsInventoryPreflight(string migrationId, SqlOperation operation)
    {
        if (migrationId != InventoryMigrationId || NormalizeDefinition(operation.Sql) != InventoryPreflightSql) return false;
        if (operation.SuppressTransaction) throw new InvalidOperationException("Delivery inventory validation must use the migration transaction.");
        return true;
    }

    internal static bool TryGetTrigger(string migrationId, SqlOperation operation,
        out (string Table, DatabaseTriggerSchema Trigger) result)
    {
        if (DeliveryTripSchemaSqlCatalog.TryGetTrigger(migrationId, operation, out result)) return true;
        result = default;
        var candidates = Entries.Where(x => x.MigrationId == migrationId).ToArray();
        if (candidates.Length == 0) return false;
        var normalized = NormalizeDefinition(operation.Sql);
        var entry = candidates.SingleOrDefault(x => NormalizeDefinition(x.Sql) == normalized);
        if (operation.SuppressTransaction || entry is null)
            throw new InvalidOperationException("Delivery migration contains an unrecognized trigger SQL operation.");
        result = (entry.Table, new(DatabaseSchemaNormalization.NormalizeIdentifier(entry.Name),
            NormalizeDefinition(entry.Sql), IsDisabled: false, IsNotForReplication: false,
            UsesAnsiNulls: true, UsesQuotedIdentifier: true));
        return true;
    }

    internal static bool TryGetProvisionalReplacementDrop(string migrationId, SqlOperation operation,
        out (string Table, string Name, string PreviousDefinition) result)
    {
        result = default;
        if (migrationId != ProvisionalMigrationId) return false;
        var sql = NormalizeDefinition(operation.Sql);
        var previous = Entries.SingleOrDefault(x => x.MigrationId == InventoryMigrationId &&
            (x.Name == "TR_DeliveryJournalEntries_StockSource" || x.Name == "TR_DeliveryDispatchCostFragments_StockSource" || x.Name == "TR_DeliveryReturnedCostFragments_StockSource") &&
            sql == "DROP TRIGGER [" + x.Name + "];" );
        if (previous is null) return false;
        if (operation.SuppressTransaction) throw new InvalidOperationException("Provisional protection replacement must use the migration transaction.");
        result = (previous.Table, DatabaseSchemaNormalization.NormalizeIdentifier(previous.Name), NormalizeDefinition(previous.Sql));
        return true;
    }
